import {esc} from './state.js';
export const colors=['#416b55','#b37542','#537e93','#8f6d96'];
export const fmt=(n,d=1)=>Number(n).toFixed(d);
export const scene=(n,caption,cls='')=>`<figure class="scene-figure ${cls}"><div class="scene-art scene-${n}" role="img" aria-label="${esc(caption)}"></div><figcaption>${esc(caption)}</figcaption></figure>`;
export function chart(series,{yLabel='氣體生成量 / mL',xMax,yMax,xLabel='時間 / s',height=245}={}){
 const W=680,H=height,L=65,R=20,T=26,B=44;const pts=series.flatMap(s=>s.data);const maxX=xMax||Math.max(10,...pts.map(p=>p.x));const maxY=yMax||Math.max(.01,...pts.map(p=>p.y))*1.15;
 const x=v=>L+v/maxX*(W-L-R),y=v=>H-B-v/maxY*(H-T-B);
 const axes=Array.from({length:5},(_,i)=>{const v=maxY*i/4,xx=maxX*i/4;return `<path d="M${L} ${y(v)}H${W-R}" stroke="#d9e1d2"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${v>=10?fmt(v,0):fmt(v,2)}</text><text x="${x(xx)}" y="${H-B+20}" text-anchor="middle">${fmt(xx,0)}</text>`;}).join('');
 return `<svg viewBox="0 0 ${W} ${H}" class="data-chart" role="img" aria-label="${esc(yLabel)}對${esc(xLabel)}曲線"><text x="${L}" y="15">${esc(yLabel)}</text>${axes}<path d="M${L} ${T}V${H-B}H${W-R}" stroke="#70836e" fill="none"/>${series.map((s,i)=>`<path d="${s.data.map((p,j)=>(j?'L':'M')+fmt(x(p.x),2)+' '+fmt(y(p.y),2)).join(' ')}" stroke="${s.color||colors[i%4]}" stroke-width="2.8" fill="none" ${s.dashed?'stroke-dasharray="7 5"':''}/>`).join('')}<text x="${W-R}" y="${H-4}" text-anchor="end">${esc(xLabel)}</text></svg><div class="chart-legend">${series.map((s,i)=>`<span><i style="background:${s.color||colors[i%4]}"></i>${esc(s.label)}</span>`).join('')}</div>`;
}
export function apparatus({id='lab',sample,mass=1,loaded=false,kind='carbonate',temperature=20,catalyst=0,time=0,label='反應瓶',baseline=false}={}){
 const s=sample||{fraction:0,volume:0,rate:0};const prefix=id+(baseline?'b':'a');const gas=Math.min(1,s.fraction);const bubbles=Math.min(16,Math.round(s.rate*.65));
 return `<svg viewBox="0 0 720 360" class="apparatus" role="img" aria-label="${esc(label)}：${fmt(s.volume)} mL，${temperature}°C"><defs><linearGradient id="glass-${prefix}"><stop stop-color="#abc7c388"/><stop offset=".3" stop-color="#ffffff88"/><stop offset=".7" stop-color="#d8eeeb22"/><stop offset="1" stop-color="#8aaca480"/></linearGradient><linearGradient id="liquid-${prefix}" x2="0" y2="1"><stop stop-color="#c7dfd5bb"/><stop offset="1" stop-color="#6e9f91aa"/></linearGradient><linearGradient id="wood-${prefix}" x2="0" y2="1"><stop stop-color="#b59973"/><stop offset="1" stop-color="#7c654b"/></linearGradient><clipPath id="flask-${prefix}"><path d="M250 107H282V158L334 270Q344 288 323 290H209Q188 288 198 270L250 158Z"/></clipPath></defs>
 <rect width="720" height="360" fill="#e3ebe4"/><path d="M0 60H720M0 120H720M0 180H720M120 0V230M360 0V230M600 0V230" stroke="#cbd8cd" stroke-width="1"/><rect y="304" width="720" height="56" fill="url(#wood-${prefix})"/><path d="M0 316H720M35 333H250M360 342H700" stroke="#5a4733" opacity=".18"/>
 <text x="23" y="31" fill="#667e70" font-size="12">${esc(label)}</text><text x="690" y="31" text-anchor="end" fill="#667e70" font-size="11">氣體以 24 L/mol 換算</text>
 <ellipse cx="268" cy="303" rx="96" ry="8" fill="#304b4022"/>
 <rect x="175" y="293" width="185" height="14" rx="4" fill="#527367"/>
 <path d="M250 107H282V158L334 270Q344 288 323 290H209Q188 288 198 270L250 158Z" fill="url(#glass-${prefix})" stroke="#6f9389" stroke-width="2.4"/>
 <g clip-path="url(#flask-${prefix})">${loaded?`<path d="M185 222Q230 216 270 222T345 222V295H185Z" fill="url(#liquid-${prefix})"/>${kind==='carbonate'?Array.from({length:Math.max(0,Math.round(10*(1-s.fraction)))},(_,i)=>`<path d="M${214+i*9} 277l5 -${8+mass*2} 7 5 -3 6Z" fill="#f6f3df" stroke="#b7b8a1"/>`).join(''):catalyst>0?Array.from({length:12},(_,i)=>`<circle cx="${215+i*8}" cy="${282-(i%3)*2}" r="2.5" fill="#3c3c32"/>`).join(''):''}${Array.from({length:bubbles},(_,i)=>{const yy=275-((time*18+i*23)%78);return `<circle cx="${228+(i*29)%73}" cy="${yy}" r="${2+i%3}" fill="#f5ffff88" stroke="#739c89" opacity=".8"/>`;}).join('')}`:''}</g>
 <path d="M256 117V160L211 265" fill="none" stroke="#ffffffbb" stroke-width="4"/>
 <path d="M242 104H291L288 121H246Z" fill="#82694b" stroke="#64543b"/>
 <path d="M267 104V78Q267 65 282 65H413Q432 65 432 85V111H460" fill="none" stroke="#63887f" stroke-width="8"/><path d="M267 104V78Q267 65 282 65H413Q432 65 432 85V111H460" fill="none" stroke="#e8f9f0" stroke-width="4"/>
 <rect x="456" y="88" width="182" height="47" rx="4" fill="url(#glass-${prefix})" stroke="#73978e" stroke-width="2"/>
 <rect x="460" y="91" width="${gas*155}" height="41" fill="#dfebc580"/><rect x="${462+gas*155}" y="90" width="8" height="43" fill="#8d9f93"/><path d="M${470+gas*155} 111H690M689 94V129" stroke="#698075" stroke-width="5"/>
 ${Array.from({length:10},(_,i)=>`<path d="M${469+i*17} 89v${i%2?9:14}" stroke="#698075"/>`).join('')}<text x="460" y="159" font-size="12" fill="#4f6d60">氣體注射筒（自由滑動活塞）</text>
 <path d="M534 136V288M497 291H578" stroke="#64786c" stroke-width="7"/><rect x="522" y="137" width="24" height="7" rx="3" fill="#9baa9b"/>
 <rect x="34" y="244" width="109" height="57" rx="6" fill="#d7ded0" stroke="#829383"/><ellipse cx="88" cy="243" rx="50" ry="10" fill="#a9b5a3" stroke="#778b7e"/><rect x="47" y="263" width="81" height="23" rx="3" fill="#334e42"/><text x="88" y="280" text-anchor="middle" fill="#e2efbc" font-size="16" font-family="monospace">${fmt(mass,2)} g</text><text x="88" y="326" text-anchor="middle" font-size="12" fill="#fff8e8">電子天平</text>
 <rect x="386" y="235" width="100" height="57" rx="6" fill="#e8e4d2" stroke="#b0a57c"/><text x="436" y="257" text-anchor="middle" fill="#778065" font-size="10">恆溫控制</text><text x="436" y="279" text-anchor="middle" fill="#466554" font-size="19">${temperature}°C</text>
 <rect x="556" y="227" width="131" height="64" rx="8" fill="#2c483c" stroke="#73836d"/><text x="621" y="248" text-anchor="middle" fill="#d1c69c" font-size="10">計時器 / 模型秒</text><text x="621" y="276" text-anchor="middle" fill="#f0f5d4" font-size="24" font-family="monospace">${fmt(time)} s</text>
 <text x="269" y="329" text-anchor="middle" fill="#fff9e9" font-size="12">${kind==='carbonate'?'CaCO₃ + 稀鹽酸':'H₂O₂'+(catalyst?' + MnO₂':'')}</text></svg>`;
}
export class ParticleView{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');}
 draw(s,{mode='equilibrium',surface=1,concentration=1}={}){const c=this.canvas,ctx=this.ctx;if(!ctx)return;c.width=720;c.height=260;ctx.fillStyle='#e7ede2';ctx.fillRect(0,0,720,260);ctx.strokeStyle='#bccab5';ctx.strokeRect(10,10,700,240);
  const units=mode==='equilibrium'?Math.round(s.units*40):Math.round(20*concentration);const b=mode==='equilibrium'?Math.round(s.n2o4/s.units*units):0;const a=mode==='equilibrium'?units-2*b:units;const speed=mode==='equilibrium'?Math.sqrt((s.temperature+273)/298):Math.sqrt(((s.temperature||20)+273)/293)*1.7;const time=s.time||0;
  for(let i=0;i<a+b;i++){const phase=i*2.399;const x=34+((i*71+time*speed*(15+i%4*6))%652);const y=35+(Math.sin(phase+time*speed*.6)+1)*(mode==='equilibrium'?60:90);const pair=i>=a;ctx.fillStyle=mode==='equilibrium'?(pair?'#b0bca7':'#a65e3f'):'#b17645';ctx.beginPath();ctx.arc(x-(pair?5:0),y,6,0,Math.PI*2);ctx.fill();if(pair){ctx.beginPath();ctx.arc(x+5,y,6,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#ffffff99';ctx.beginPath();ctx.arc(x-2,y-2,1.8,0,Math.PI*2);ctx.fill();}
  if(mode==='equilibrium'){ctx.fillStyle='#f8faeee8';ctx.fillRect(12,180,696,68);ctx.font='12px Microsoft JhengHei';for(let dir=0;dir<2;dir++){const phase=((dir?s.reverseEvents:s.forwardEvents)*7)%1;const separation=dir?6+phase*35:6+(1-phase)*35;const x=dir?510:170;ctx.fillStyle='#6b7f60';ctx.fillText(dir?'逆向：N₂O₄ → 2 NO₂':'正向：2 NO₂ → N₂O₄',x-80,195);ctx.fillStyle=(dir?phase<.35:phase>.65)?'#aebca2':'#a65e3f';for(const sign of [-1,1]){ctx.beginPath();ctx.arc(x+sign*separation,218,7,0,Math.PI*2);ctx.fill();}}ctx.fillStyle='#8d977e';ctx.font='10px Microsoft JhengHei';ctx.fillText('下方為雙向轉換的放大示意，進度由模型反應事件量驅動，不另計入上方粒子總數。',65,244);}
  if(mode!=='equilibrium'){ctx.fillStyle='#668971';for(let i=0;i<surface;i++){const x=160+i*90;ctx.fillRect(x,174,Math.max(14,80/surface),50);}ctx.fillStyle='#8b623c';ctx.font='13px Microsoft JhengHei';ctx.fillText('碰撞不一定有效；位置、數量與閃光為觀念示意',20,245);}
 }
}
